SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS franzoesisch_woerter_und_saetze
(
    id INT UNSIGNED NOT NULL AUTO_INCREMENT,
    lektion INT UNSIGNED NOT NULL,
    thema_d VARCHAR(255) NOT NULL,
    thema_f VARCHAR(255) NOT NULL,
    wort_d TEXT NOT NULL,
    wort_f TEXT NOT NULL,
    PRIMARY KEY (id),
    INDEX idx_lektion (lektion),
    INDEX idx_thema_d (thema_d),
    INDEX idx_thema_f (thema_f)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
